const p = $json.body ?? $json;
const allowed = ['sheet', 'email', 'whatsapp', 'task', 'study', 'calendar'];
if (!allowed.includes(p.action)) throw new Error('Acción no válida');
const content = String(p.content ?? '').trim();
if (!content) throw new Error('El contenido está vacío');
if (content.length > 10000) throw new Error('El contenido supera 10 000 caracteres');
const recipient = String(p.recipient ?? '').trim();
if (p.action === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient)) throw new Error('Escribe un correo destinatario válido');
const urgentWords = /urgente|hoy|inmediato|prioridad alta|asap/i;
const mediumWords = /mañana|esta semana|pendiente|importante/i;
const priority = urgentWords.test(content) ? 'alta' : mediumWords.test(content) ? 'media' : 'normal';
const labels = { sheet: 'Registro CSV local', email: 'Email local', whatsapp: 'WhatsApp local', task: 'Plan de tareas', study: 'Sesión de estudio', calendar: 'Evento de calendario' };
return [{ json: { requestId: `nx-${Date.now().toString(36)}`, action: p.action, actionLabel: labels[p.action], recipient, subject: String(p.subject ?? 'Solicitud NEXORA').trim() || 'Solicitud NEXORA', content, priority, source: 'NEXORA AI', receivedAt: new Date().toISOString(), approvalRequired: false } }];

const fs = require('fs');
const file = '/files/nexora-events.jsonl';
for (const item of items) fs.appendFileSync(file, `${JSON.stringify(item.json)}\n`, 'utf8');
return items.map(item => ({ json: { ...item.json, storedLocally: true, localFile: file } }));

const fs = require('fs');
const path = require('path');
const p = $json;
const root = '/files/outputs';
fs.mkdirSync(root, { recursive: true });
const lines = p.content.split(/\n|[.;](?:\s+|$)/).map(x => x.trim()).filter(Boolean).slice(0, 8);
const safe = value => String(value).replace(/[\r\n]/g, ' ').trim();
const csv = value => `\"${String(value).replace(/\"/g, '\"\"')}\"`;
let automation;
switch (p.action) {
  case 'sheet': {
    const file = path.join(root, 'registro-nexora.csv');
    if (!fs.existsSync(file)) fs.writeFileSync(file, 'id,fecha,asunto,contenido,prioridad\n', 'utf8');
    fs.appendFileSync(file, [p.requestId, p.receivedAt, p.subject, p.content, p.priority].map(csv).join(',') + '\n', 'utf8');
    automation = { type: 'local_csv', file, columns: { id: p.requestId, fecha: p.receivedAt, asunto: p.subject, contenido: p.content, prioridad: p.priority }, status: 'fila guardada' };
    break;
  }
  case 'email':
    automation = { type: 'email_delivery', to: p.recipient, subject: p.subject, body: p.content, status: 'enviando al buzón local' };
    break;
  case 'whatsapp': {
    const file = path.join(root, 'whatsapp-outbox.jsonl');
    const entry = { id: p.requestId, to: p.recipient || 'POR DEFINIR', message: p.content, createdAt: p.receivedAt, status: 'listo para demostración local' };
    fs.appendFileSync(file, JSON.stringify(entry) + '\n', 'utf8');
    automation = { type: 'whatsapp_local_outbox', file, ...entry };
    break;
  }
  case 'task': {
    const file = path.join(root, `${p.requestId}-tareas.md`);
    const checklist = lines.map((text, index) => ({ order: index + 1, text, done: false }));
    fs.writeFileSync(file, `# ${safe(p.subject)}\n\nPrioridad: ${p.priority}\n\n${checklist.map(x => `- [ ] ${x.text}`).join('\n')}\n`, 'utf8');
    automation = { type: 'task_plan', file, priority: p.priority, checklist, status: 'archivo Markdown creado' };
    break;
  }
  case 'study': {
    const file = path.join(root, `${p.requestId}-estudio.md`);
    const blocks = [{ minutes: 10, activity: 'Lectura y conceptos', material: p.content }, { minutes: 20, activity: 'Práctica activa', material: 'Explicar sin mirar y crear ejemplos' }, { minutes: 10, activity: 'Autoevaluación', material: 'Responder cinco preguntas y revisar errores' }];
    fs.writeFileSync(file, `# ${safe(p.subject)}\n\n${blocks.map(x => `## ${x.minutes} min · ${x.activity}\n${x.material}`).join('\n\n')}\n`, 'utf8');
    automation = { type: 'study_session', file, blocks, totalMinutes: 40, status: 'plan guardado' };
    break;
  }
  case 'calendar': {
    const start = new Date(Date.now() + 24 * 60 * 60 * 1000);
    start.setHours(15, 0, 0, 0);
    const end = new Date(start.getTime() + 60 * 60 * 1000);
    const icsDate = date => date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
    const file = path.join(root, `${p.requestId}-evento.ics`);
    const ics = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//NEXORA AI//Local//ES','BEGIN:VEVENT',`UID:${p.requestId}@nexora.local`,`DTSTAMP:${icsDate(new Date())}`,`DTSTART:${icsDate(start)}`,`DTEND:${icsDate(end)}`,`SUMMARY:${safe(p.subject)}`,`DESCRIPTION:${safe(p.content)}`,'END:VEVENT','END:VCALENDAR',''].join('\r\n');
    fs.writeFileSync(file, ics, 'utf8');
    automation = { type: 'calendar_ics', file, title: p.subject, scheduledFor: start.toISOString(), status: 'invitación ICS creada' };
    break;
  }
}
return [{ json: { ok: true, app: 'NEXORA AI', requestId: p.requestId, action: p.action, label: p.actionLabel, priority: p.priority, approvalRequired: false, storedLocally: p.storedLocally, message: `${p.actionLabel} ejecutado correctamente en n8n local`, automation, nextSteps: p.action === 'email' ? ['Abrir http://localhost:8025 para ver el correo'] : ['Revisar el artefacto dentro de n8n-local/outputs'] } }];
